    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000015'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000015'), 1, 'SELECT name, department, salary\nFROM employees\nWHERE salary IS NULL;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
