    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000017'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000017'), 1, 'SELECT name, city, signup_date\nFROM customers\nORDER BY city, signup_date DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000018'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000018'), 2, 'SELECT name, salary\nFROM employees\nORDER BY salary DESC NULLS LAST;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000019'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000019'), 1, 'SELECT id, customer_id, order_date, status\nFROM orders\nORDER BY order_date DESC\nLIMIT 5;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000020'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000020'), 1, 'SELECT order_id, quantity * unit_price AS line_total\nFROM order_items\nWHERE quantity * unit_price > 10000000\nORDER BY line_total DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000021'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000013'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000021'), 1, 'SELECT name, hire_date,\n       CASE\n           WHEN hire_date < ''2021-01-01'' THEN ''Lâu năm''\n           WHEN hire_date < ''2024-01-01'' THEN ''Ổn định''\n           ELSE ''Mới''\n       END AS seniority\nFROM employees\nORDER BY hire_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000022'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000014'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000022'), 1, 'SELECT id, name, UPPER(REPLACE(name, '' '', ''-'')) AS product_code\nFROM products;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000023'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000014'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000023'), 2, 'SELECT name, SUBSTRING(name FROM 1 FOR POSITION('' '' IN name) - 1) AS family_name\nFROM employees;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000024'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000015'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000024'), 1, 'SELECT id, order_date, status\nFROM orders\nWHERE EXTRACT(MONTH FROM order_date) BETWEEN 10 AND 12\nORDER BY order_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e001-0000-7000-8000-600000000025'), UUID_TO_BIN('01a1e001-0000-7000-8000-400000000015'), UUID_TO_BIN('01a1e001-0000-7000-8000-700000000025'), 2, 'SELECT name, signup_date,\n       DATE ''2026-01-01'' - signup_date AS days_since_signup,\n       TO_CHAR(signup_date, ''DD/MM/YYYY'') AS signup_vn\nFROM customers\nORDER BY days_since_signup DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
